def get_provider_icon(provider: str, color: str, size: int = 22) -> QIcon:
    """Render bundled provider marks without network access at runtime."""
    names = {'Google Translate': 'google', 'Google Gemini': 'gemini', 'OpenAI': 'openai', 'DeepSeek': 'deepseek'}
    name = names.get(provider)
    if name is None:
        return get_lucide_icon('link', color, size)
    # QtSvg requires separated SVG arc flags (upstream paths are minified).
    svg = PROVIDER_COLOR_MARKS.get(name, PROVIDER_MARKS[name]).replace(' 0 01', ' 0 0 1 ').replace(' 0 00', ' 0 0 0 ')
    renderer = QSvgRenderer(QByteArray(svg.replace('currentColor', color).encode('utf-8')))
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()
    return QIcon(pixmap)
